-- ===========================================
-- Phase 7: C3 Form/Contribution Tables
-- ===========================================

-- PROCESS_C3Header table
CREATE TABLE public."PROCESS_C3Header" (
  "C3HeaderID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "CompanyID" INTEGER REFERENCES public."MasterCompany"("CompanyID"),
  "Period_Year" VARCHAR(10),
  "Period_Month" VARCHAR(10),
  "RegNumber" VARCHAR(50),
  "CompanyName" VARCHAR(200),
  "Address1" VARCHAR(500),
  "Address2" VARCHAR(500),
  "City" VARCHAR(100),
  "State" VARCHAR(100),
  "Zip" VARCHAR(20),
  "Phone" VARCHAR(50),
  "Fax" VARCHAR(50),
  "Email" VARCHAR(200),
  "TotalEmployees" INTEGER,
  "TotalInsurable" NUMERIC(18,2),
  "TotalSS_EE" NUMERIC(18,2),
  "TotalSS_ER" NUMERIC(18,2),
  "TotalSeverance" NUMERIC(18,2),
  "TotalLevy_EE" NUMERIC(18,2),
  "TotalLevy_ER" NUMERIC(18,2),
  "TotalContribution" NUMERIC(18,2),
  "Penalty" NUMERIC(18,2),
  "Fine" NUMERIC(18,2),
  "GrandTotal" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "SubmittedDate" TIMESTAMP WITH TIME ZONE,
  "ApprovedDate" TIMESTAMP WITH TIME ZONE,
  "ApprovedBy" INTEGER,
  "RejectedDate" TIMESTAMP WITH TIME ZONE,
  "RejectedBy" INTEGER,
  "RejectReason" TEXT,
  "PaymentStatus" VARCHAR(50),
  "PaymentDate" TIMESTAMP WITH TIME ZONE,
  "PaymentReference" VARCHAR(100),
  "IsFiled" BOOLEAN DEFAULT FALSE,
  "IsLocked" BOOLEAN DEFAULT FALSE,
  "Deletable" BOOLEAN DEFAULT TRUE,
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(500),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(500),
  "C3Type" VARCHAR(50),
  "Remarks" TEXT
);

-- Process_Contributions table
CREATE TABLE public."Process_Contributions" (
  "ContributionID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "C3HeaderID" INTEGER REFERENCES public."PROCESS_C3Header"("C3HeaderID"),
  "CompanyID" INTEGER,
  "EmployeeID" INTEGER REFERENCES public."MasterEmployee"("EmpID"),
  "Period_Year" VARCHAR(10),
  "Period_Month" VARCHAR(10),
  "Soc_Sec_Num" VARCHAR(50),
  "First_Name" VARCHAR(100),
  "Middle_Name" VARCHAR(100),
  "Last_Name" VARCHAR(100),
  "BirthDate" TIMESTAMP WITH TIME ZONE,
  "Gender" VARCHAR(10),
  "WageCategory" VARCHAR(100),
  "InsurableEarnings" NUMERIC(18,2),
  "SS_EE_Rate" NUMERIC(10,4),
  "SS_ER_Rate" NUMERIC(10,4),
  "SS_EE" NUMERIC(18,2),
  "SS_ER" NUMERIC(18,2),
  "Severance_Rate" NUMERIC(10,4),
  "Severance" NUMERIC(18,2),
  "Levy_EE_Rate" NUMERIC(10,4),
  "Levy_ER_Rate" NUMERIC(10,4),
  "Levy_EE" NUMERIC(18,2),
  "Levy_ER" NUMERIC(18,2),
  "TotalContribution" NUMERIC(18,2),
  "IsDirector" BOOLEAN DEFAULT FALSE,
  "IsDirectorOnly" BOOLEAN DEFAULT FALSE,
  "IsLevyExempt" BOOLEAN DEFAULT FALSE,
  "WeeksWorked" INTEGER,
  "DaysWorked" INTEGER,
  "HoursWorked" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "Remarks" TEXT,
  "Deletable" BOOLEAN DEFAULT TRUE,
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(500),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(500),
  "Empl_Code" VARCHAR(50),
  "Pay_Period" VARCHAR(20),
  "Joining_Date" TIMESTAMP WITH TIME ZONE,
  "Termination_Date" TIMESTAMP WITH TIME ZONE
);

