  "Levy_EE_Rate" NUMERIC(10,4),
  "Levy_EE" NUMERIC(18,2),
  "TotalContribution" NUMERIC(18,2),
  "Penalty" NUMERIC(18,2),
  "Fine" NUMERIC(18,2),
  "GrandTotal" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "SubmittedDate" TIMESTAMP WITH TIME ZONE,
  "ApprovedDate" TIMESTAMP WITH TIME ZONE,
  "ApprovedBy" INTEGER,
  "PaymentStatus" VARCHAR(50),
  "PaymentDate" TIMESTAMP WITH TIME ZONE,
  "PaymentReference" VARCHAR(100),
  "IsFiled" BOOLEAN DEFAULT FALSE,
  "IsLocked" BOOLEAN DEFAULT FALSE,
  "Deletable" BOOLEAN DEFAULT TRUE,
  "InsertedBy" INTEGER,
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "InsertedMachineInfo" VARCHAR(500),
  "UpdatedBy" INTEGER,
  "UpdatedOn" TIMESTAMP WITH TIME ZONE,
  "UpdatedMachineInfo" VARCHAR(500),
  "Remarks" TEXT
);

