-- EmployeeTCard_Header table
CREATE TABLE public."EmployeeTCard_Header" (
  "TCardHeaderID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "CompanyID" INTEGER,
  "EmployeeID" INTEGER,
  "PeriodStart" TIMESTAMP WITH TIME ZONE,
  "PeriodEnd" TIMESTAMP WITH TIME ZONE,
  "TotalHours" NUMERIC(18,2),
  "Status" VARCHAR(50),
  "InsertedOn" TIMESTAMP WITH TIME ZONE DEFAULT NOW(),
  "UpdatedOn" TIMESTAMP WITH TIME ZONE
);

-- EmployeeTCard_Details table
CREATE TABLE public."EmployeeTCard_Details" (
  "TCardDetailID" INTEGER PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "TCardHeaderID" INTEGER REFERENCES public."EmployeeTCard_Header"("TCardHeaderID"),
